    [1240686] = { en = "Increases the time between nearby enemies' attacks by $s1% and slows their movement and casting speed by $s2% for $d.", description = "Aumenta del $s1% l'intervallo tra gli attacchi dei nemici vicini e ne riduce la velocità di movimento e di lancio degli incantesimi del $s2% per $d." },
