    [1269268] = { en = "Inflicts $s1 Fire damage and stuns targets in a 5 yard radius for $d.  Any damage will break the effect.", description = "Infligge $s1 danni da fuoco e stordisce per $d i bersagli entro 5 metri. Qualsiasi danno interrompe l'effetto." },
