    [1287561] = { en = "Increases damage and healing done by magical spells and effects by up to $s1. This effect is tripled in Forest and Grassland areas.", description = "Aumenta fino a $s1 i danni inflitti e le cure fornite da incantesimi ed effetti magici. L'effetto triplica nelle aree di foresta e prateria." },
