    [1288471] = { en = "Throws a glaive at an enemy, inflicting Physical damage and then bouncing to nearby targets.\r\n", description = "Scaglia un gladio contro un nemico, infliggendo danni fisici prima che rimbalzi sui bersagli vicini.\r\n" },
    [1289428] = { en = "Another mug, aye.", description = "Un altro boccale, sì." },
