    [1291345] = { en = "Smash the target item into scrap to recover a small quantity of usable crafting materials. All camping features share a cooldown of $1308027d.", description = "Distrugge l'oggetto bersaglio per recuperarne una piccola quantità di materiali da creazione utilizzabili. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1291906] = { en = "After entering combat, reduce the next instance of physical damage taken within $1291908d by $1291908s1.", description = "Dopo essere entrato in combattimento, riduce i danni fisici subiti entro $1291908d di $1291908s1." },
    [1292039] = { en = "Deals $s1 Physical damage every time you block.", description = "Infligge $s1 danni fisici ogni volta che blocchi." },
    [1292652] = { en = "Reduces the hit chance of Sleep effects against you by $s1%.", description = "Riduce del $s1% la probabilità che gli effetti di Sonno ti colpiscano." },
    [1292997] = { en = "Increase experience gained from slaying Undead by $s1% for $d.", description = "Aumenta del $s1% l'esperienza ottenuta uccidendo Non Morti per $d." },
    [1293107] = { en = "Increases your Legacy reputation by $s1.\r\n", description = "Aumenta la tua reputazione presso Legacy di $s1.\r\n" },
    [1293518] = { en = "Assault the target with a dangerous toxin, dealing $s1 Nature damage. Deals $s2 times as much damage to Plants.", description = "Avvelena il bersaglio con una tossina pericolosa, infliggendo $s1 danni da natura. Infligge danni moltiplicati per $s2 alle piante." },
    [1293782] = { en = "Spells and attacks against Swine deal $1292675s1 Nature damage.", description = "Gli incantesimi e gli attacchi contro i suini infliggono $1292675s1 danni da natura." },
