    [1294462] = { en = "Slips into the shadows, reducing the chance for enemies to detect your presence. Lasts until cancelled or upon moving", description = "Si fonde con le ombre, riducendo la probabilità che i nemici si accorgano della tua presenza. Dura finché non viene annullato o finché non ti muovi" },
    [1294683] = { en = "The light of the Elune periodically empowers anyone residing within the moonwell.", description = "La luce di Elune conferisce periodicamente potere a chiunque si trovi nel Pozzo Lunare." },
