    [1297659] = { en = "Teleports the caster to Dalaran.", description = "Teletrasporta l'incantatore a Dalaran." },
    [1298230] = { en = "After entering combat, reduce the next instance of physical damage taken within $1298231d by $1298231s1.", description = "Dopo essere entrato in combattimento, riduce i danni fisici subiti entro $1298231d di $1298231s1." },
