    [1298841] = { en = "The spirit struggles to maintain its form, suffering $s1% of maximum health as damage every $t1 sec.\r\n", description = "Lo spirito fatica a mantenere la propria forma e subisce danni pari al $s1% della salute massima ogni $t1 secondi.\r\n" },
    [1299094] = { en = "Attempt to Stun other players who also have a Replica Ironforge Air Rifle equipped.", description = "Tenta di stordire gli altri giocatori che hanno equipaggiato una Replica Ironforge Air Rifle." },
    [1299754] = { en = "Increases damage done to Dragonkin by magical spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti ai dragoni da incantesimi ed effetti magici." },
    [1300176] = { en = "Blasts the target with energy, dealing Arcane damage.  Each time you cast Arcane Blast, the damage of all other spells is increased by $400573s1% and mana cost of Arcane Blast is increased by $400573s2%.  Effect stacks up to $400573u times and lasts $400573d.", description = "Colpisce il bersaglio con un'esplosione di energia, infliggendo danni arcani. Ogni lancio di Arcane Blast aumenta del $400573s1% i danni di tutti gli altri incantesimi e del $400573s2% il costo in mana di Arcane Blast. L'effetto si accumula fino a $400573u volte e dura $400573d." },
    [1300438] = { en = "Deals $s1 Arcane damage.", description = "Infligge $s1 danni arcani." },
    [1301073] = { en = "Increases damage done by your spells and effects by up to $s1 when fighting Demons.", description = "Aumenta fino a $s1 i danni inflitti dai tuoi incantesimi ed effetti quando combatti i demoni." },
    [1301079] = { en = "Increases damage done by your spells and effects by up to $s1 when fighting Elementals.", description = "Aumenta fino a $s1 i danni inflitti dai tuoi incantesimi ed effetti quando combatti gli elementali." },
    [1302112] = { en = "Hold forth the Torch of Eternal Flame.", description = "Brandisci la Torch of Eternal Flame." },
