    [1306384] = { en = "Combine 20 Mathystral Amulet Fragments into a restored Mathystral Amulet.", description = "Combina 20 Mathystral Amulet Fragments per ricostruire il Mathystral Amulet." },
    [1306396] = { en = "Beckon forth the being guarding the Mathystral Ruins at a Fathom Stone.", description = "Richiama l'essere che sorveglia Mathystral Ruins presso una Fathom Stone." },
    [1306608] = { en = "Call a Sentinel to monitor an area.", description = "Richiama una Sentinella per sorvegliare un'area." },
