    [1309730] = { en = "Right Click to summon and dismiss your ground squirrel.", description = "Clic destro per evocare o congedare il tuo scoiattolo terrestre." },
    [1309957] = { en = "Improves your chance to hit with Holy spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpire con gli incantesimi sacri." },
    [1311676] = { en = "Curses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.\r\n", description = "Maledice il bersaglio per $d, riducendone le resistenze alla magia di $s1 e aumentando i danni magici subiti del $s2%. Ogni stregone può mantenere una sola maledizione attiva sullo stesso bersaglio.\r\n" },
    [1312880] = { en = "Right Click to summon and dismiss your baby crocolisk.", description = "Clic destro per evocare o congedare il tuo piccolo crocolisco." },
    [1314305] = { en = "Puncture the target, inflicting $s1 Physical damage.", description = "Perfora il bersaglio, infliggendo $s1 danni fisici." },
    [1314784] = { en = "Increases Strength by $s1 while affected by a Bleed.", description = "Aumenta la Forza di $s1 mentre sei soggetto a un effetto di sanguinamento." },
    [1315996] = { en = "Deals $s1 Nature damage.", description = "Infligge $s1 danni da natura." },
    [1316053] = { en = "Restores $s1 Mana per 5 sec. Restores an additional $1316054s1 Mana per 5 sec in Forest and Grassland areas.", description = "Rigenera $s1 mana ogni 5 secondi. Nelle aree di foresta e prateria rigenera altri $1316054s1 mana ogni 5 secondi." },
