    [1317285] = { en = "Reduces your damage taken by $s1% in the Battle Ring and The Maul.", description = "Riduce del $s1% i danni subiti nelThe Battle Ring and The Maul." },
    [1318000] = { en = "+$s1 Attack Power. This effect is tripled in Forest and Grassland areas.", description = "+$s1 potenza d'attacco. L'effetto triplica nelle aree di foresta e prateria." },
    [1318102] = { en = "Increases all Resistances by $s1. Gain an additional $1318103s1 to all Resistances in Forest and Grassland areas.", description = "Aumenta tutte le resistenze di $s1. Nelle aree di foresta e prateria ottieni altri $1318103s1 a tutte le resistenze." },
    [1318124] = { en = "Restores $s1 Mana per 5 sec. Restores an additional $1318125s1 Mana per 5 sec in Forest and Grassland areas.", description = "Rigenera $s1 mana ogni 5 secondi. Nelle aree di foresta e prateria rigenera altri $1318125s1 mana ogni 5 secondi." },
    [1318476] = { en = "Increases spell damage and healing by up to $s1. Grants an additional $s3 spell damage against Demons.", description = "Aumenta fino a $s1 i danni degli incantesimi e le cure. Contro i demoni, aumenta inoltre i danni degli incantesimi di $s3." },
    [1321936] = { en = "A putrid cloud of disease surrounds the caster, dealing Nature damage to nearby enemies.\r\n", description = "Una nube pestilenziale avvolge l'incantatore e infligge danni da natura ai nemici vicini.\r\n" },
    [10] = { en = "Ice shards pelt the target area doing ${$1279976m1*$d*$<frostdamage>} Frost damage over $d.", description = "Schegge di ghiaccio investono l'area bersaglio, infliggendo ${$1279976m1*$d*$<frostdamage>} danni da gelo nell'arco di $d." },
    [89] = { en = "Cripples the target, reducing movement speed by $s3%, increasing time between melee attacks by $s1% and increasing time between ranged attacks by $s2%.  Lasts $d.", description = "Azzoppa il bersaglio, riducendone la velocità di movimento del $s3%, aumentando del $s1% l'intervallo tra gli attacchi in mischia e del $s2% quello tra gli attacchi a distanza. Dura $d." },
    [132] = { en = "Allows the friendly target to detect lesser invisibility for $d.", description = "Permette al bersaglio alleato di individuare l'invisibilità inferiore per $d." },
    [184] = { en = "Surrounds an ally with a shield of flame that inflicts $3053s1 Fire damage to nearby enemies every $t1 sec.  Lasts $d.", description = "Avvolge un alleato con uno scudo di fiamme che infligge $3053s1 danni da fuoco ai nemici vicini ogni $t1 secondi. Dura $d." },
    [265] = { en = "Kills all enemies in a 30 yard radius.  Cheater.", description = "Uccide tutti i nemici entro un raggio di 30 metri. Imbroglione." },
    [325] = { en = "The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26365s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.", description = "L'incantatore è circondato da $n sfere di fulmini. Quando viene colpito da un incantesimo o da un attacco in mischia o a distanza, l'attaccante subisce $26365s1 danni da natura. La sfera si consuma all'impatto. Può attivarsi una sola sfera ogni pochi secondi. Dura $d." },
    [370] = { en = "Purges the enemy target, removing $m1 magic $leffect:effects;.", description = "Purga il bersaglio nemico, rimuovendo $m1 effetti $leffect:effects; magici." },
    [408] = { en = "Finishing move that stuns the target.  Lasts longer per combo point:\r\n   1 point  : 1 second\r\n   2 points: 2 seconds\r\n   3 points: 3 seconds\r\n   4 points: 4 seconds\r\n   5 points: 5 seconds", description = "Mossa finale che stordisce il bersaglio. La durata aumenta in base ai punti combo:\r\n   1 punto  : 1 secondo\r\n   2 punti: 2 secondi\r\n   3 punti: 3 secondi\r\n   4 punti: 4 secondi\r\n   5 punti: 5 secondi" },
    [458] = { en = "Summons and dismisses a rideable brown horse.", description = "Evoca o congeda un cavallo marrone da sella." },
    [552] = { en = "Attempts to cure $s2 disease effect on the target, and $10872s1 more disease effect every $t1 seconds for $d.", description = "Tenta di curare $s2 effetto di malattia sul bersaglio e $10872s1 altri effetti ogni $t1 secondi per $d." },
    [603] = { en = "Afflicts the target with impending doom, causing $s1 Shadow damage after $d.  If the target dies from this damage, there is a chance that a Doomguard will be summoned.  Cannot be cast on players. Only one Bane per Warlock can be active on any one target.\r\n", description = "Colpisce il bersaglio con una rovina imminente, infliggendo $s1 danni da ombra dopo $d. Se il bersaglio muore per questi danni, esiste la possibilità di evocare un Guardiano della Rovina. Non può essere lanciato sui giocatori. Ogni stregone può mantenere una sola Rovina attiva sullo stesso bersaglio.\r\n" },
    [693] = { en = "Creates a Minor Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $3026s1 health and $3026q1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra dell'Anima Minore, che può custodire l'anima di un bersaglio. Se il bersaglio muore mentre la sua anima è custodita, può risorgere con $3026s1 salute e $3026q1 mana.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [775] = { en = "Transforms the druid into a tree form, removing all harmful physical effects and protecting from all physical attacks for $d, but during that time you cannot attack, move or cast spells.  Also protects the caster from polymorph effects.\r\n\r\nThe act of shapeshifting frees the caster of roots, snares, and freeze effects.", description = "Trasforma il druido in un albero, rimuovendo tutti gli effetti fisici nocivi e proteggendolo dagli attacchi fisici per $d. Durante questo periodo non puoi attaccare, muoverti o lanciare incantesimi. Protegge inoltre l'incantatore dagli effetti di metamorfosi.\r\n\r\nLa mutazione libera l'incantatore dagli effetti di immobilizzazione, intrappolamento e congelamento." },
    [776] = { en = "Abolishes all magic on the friendly target, and prevents any magic from affecting the target for $d.", description = "Dissolve tutta la magia sul bersaglio alleato e gli impedisce di subire effetti magici per $d." },
    [784] = { en = "Teaches Faerie Fire (Rank 1).", description = "Insegna Faerie Fire (grado 1)." },
    [835] = { en = "Stuns target for $d. Naga are Stunned for $1317288d and refund $1317288s2% of the cooldown.", description = "Stordisce il bersaglio per $d. I Naga restano storditi per $1317288d e recuperano il $1317288s2% del tempo di recupero." },
    [905] = { en = "The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26366s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.", description = "L'incantatore è circondato da $n sfere di fulmini. Quando viene colpito da un incantesimo o da un attacco in mischia o a distanza, l'attaccante subisce $26366s1 danni da natura. La sfera si consuma all'impatto. Può attivarsi una sola sfera ogni pochi secondi. Dura $d." },
    [1002] = { en = "Take direct control of your pet and see through its eyes for $d.", description = "Assumi il controllo diretto del tuo famiglio e guarda attraverso i suoi occhi per $d." },
    [1044] = { en = "Places a Blessing on the friendly target, granting immunity to movement impairing effects for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il bersaglio alleato, rendendolo immune agli effetti che ostacolano il movimento per $d. Ogni paladino può mantenere una sola Benedizione alla volta su ciascun giocatore." },
    [1066] = { en = "Shapeshift into aquatic form, increasing swim speed by $5421s1% and allowing the druid to breathe underwater.  Also protects the caster from Polymorph effects.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Assumi forma acquatica, aumentando del $5421s1% la velocità di nuoto e permettendo al druido di respirare sott'acqua. Protegge inoltre l'incantatore dagli effetti di metamorfosi.\r\n\r\nLa mutazione libera l'incantatore dagli effetti di metamorfosi e da quelli che ostacolano il movimento." },
    [1139] = { en = "Increases time between target's attacks by $s2% and reduces their movement speed by $s1% for $d.", description = "Aumenta del $s2% l'intervallo tra gli attacchi del bersaglio e ne riduce la velocità di movimento del $s1% per $d." },
    [1152] = { en = "Purifies the friendly target, removing $s1 disease effect and $s2 poison effect.", description = "Purifica il bersaglio alleato, rimuovendo $s1 effetto di malattia e $s2 effetto di veleno." },
    [1161] = { en = "Forces all nearby enemies within $a yards to focus attacks on you for $d.", description = "Costringe tutti i nemici vicini entro $a metri a concentrare gli attacchi su di te per $d." },
    [1181] = { en = "Restores 12 health per minute.", description = "Rigenera 12 salute al minuto." },
    [1182] = { en = "Restores 24 health per minute.", description = "Rigenera 24 salute al minuto." },
    [1499] = { en = "Place a Frost trap that freezes the first enemy that approaches, preventing all action for up to $3355d.  Any damage caused will break the ice. Trap will exist for $d. Only one Frost trap can be active at a time.", description = "Piazza una trappola gelida che congela il primo nemico che si avvicina, impedendogli di agire per un massimo di $3355d. Qualsiasi danno rompe il ghiaccio. La trappola resta attiva per $d. Puoi avere una sola trappola gelida attiva alla volta." },
    [1510] = { en = "Continuously fires a volley of ammo at the target area, causing $1279721s1 Arcane damage to enemy targets within $a1 yards every $t3 sec for $d.", description = "Scaglia ripetutamente una raffica di proiettili nell'area bersaglio, infliggendo $1279721s1 danni arcani ai nemici entro $a1 metri ogni $t3 secondi per $d." },
    [1698] = { en = "A rapid-fire attack that hits all nearby enemies in a cone in front of the warrior for weapon damage plus $s1 damage.", description = "Un attacco rapido che colpisce tutti i nemici vicini in un cono davanti al guerriero, infliggendo i danni dell'arma più $s1 danni." },
    [1706] = { en = "Allows the caster to levitate, floating a few feet above the ground. While levitating, you will fall at a reduced speed and travel over water-like surfaces. Mounting or any damage taken will cancel the effect. Lasts $d.", description = "Permette all'incantatore di levitare a pochi centimetri dal suolo. Mentre leviti, cadi più lentamente e puoi attraversare superfici simili all'acqua. Montare in sella o subire danni annulla l'effetto. Dura $d." },
    [1719] = { en = "The warrior will gain $s1% increased critical strike chance and will be immune to Fear effects for the next $d, but all damage taken is increased by $s2%.", description = "La probabilità di colpo critico del guerriero aumenta del $s1% e il guerriero diventa immune agli effetti di paura per i prossimi $d, ma i danni subiti aumentano del $s2%." },
    [1725] = { en = "Throws a distraction, attracting the attention of all nearby enemies and reducing their Stealth detection as if they were ${$m2/-5} $Llevel:levels; lower for $s1 seconds. Does not break stealth.", description = "Crea un diversivo che attira l'attenzione dei nemici vicini e ne riduce la capacità di individuare i bersagli furtivi come se fossero ${$m2/-5} $Llevel:levels; più bassi per $s1 secondi. Non interrompe la furtività." },
    [1857] = { en = "Allows the rogue to vanish from sight, entering an improved stealth mode for $11329d.  Also breaks movement impairing effects. More effective than Vanish (Rank 1).", description = "Permette al furfante di sparire alla vista, entrando in una furtività potenziata per $11329d. Rimuove anche gli effetti che ostacolano il movimento. Più efficace di Svanire (grado 1)." },
    [1906] = { en = "Charge an enemy - slowing their movement for $d.", description = "Carica un nemico e ne rallenta il movimento per $d." },
    [1949] = { en = "Ignites the area surrounding the caster, causing $s2 Fire damage to $ghimself:herself; and $5857s1 Fire damage to all nearby enemies every $t2 sec.  Lasts $d.", description = "Incendia l'area intorno all'incantatore, infliggendo $s2 danni da fuoco a $gsé stesso:sé stessa; e $5857s1 danni da fuoco a tutti i nemici vicini ogni $t2 secondi. Dura $d." },
    [1953] = { en = "Teleports the caster 20 yards forward, unless something is in the way. Also frees the caster from Stuns and Immobilizes.", description = "Teletrasporta l'incantatore 20 metri in avanti, a meno che non ci sia un ostacolo. Libera inoltre l'incantatore da stordimenti e immobilizzazioni." },
    [2096] = { en = "Allows the caster to see through the target's eyes for $d.", description = "Permette all'incantatore di guardare attraverso gli occhi del bersaglio per $d." },
    [2120] = { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage and an additional ${$1279983m1*4} Fire damage over $d. Only one Flamestrike can be active per Mage at a time.", description = "Fa cadere una colonna di fuoco che brucia tutti i nemici nell'area, infliggendo $s1 danni da fuoco e altri ${$1279983m1*4} danni da fuoco nell'arco di $d. Ogni mago può avere una sola Flamestrike attiva alla volta." },
    [2121] = { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage and an additional ${$1279985m1*4} Fire damage over $d. Only one Flamestrike can be active per Mage at a time.", description = "Fa cadere una colonna di fuoco che brucia tutti i nemici nell'area, infliggendo $s1 danni da fuoco e altri ${$1279985m1*4} danni da fuoco nell'arco di $d. Ogni mago può avere una sola Flamestrike attiva alla volta." },
    [2336] = { en = "Allows you to comprehend the common language of the opposite faction for $d.", description = "Ti permette di comprendere la lingua comune della fazione opposta per $d." },
    [2362] = { en = "Creates a Spellstone which can be used to enchant your weapon with Shadow, increasing your spell haste by $1237162s2% and the damage done by your Shadow spells by up to $1237162s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.\r\n", description = "Crea una Pietra Magica che incanta la tua arma con l'ombra, aumentando del $1237162s2% la celerità degli incantesimi e fino a $1237162s1 i danni dei tuoi incantesimi d'ombra.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti.\r\n" },
    [2458] = { en = "An aggressive stance. Critical strike chance increased by $7381s1% and all damage taken is increased by $7381s2%.", description = "Una postura aggressiva. La probabilità di colpo critico aumenta del $7381s1% e tutti i danni subiti aumentano del $7381s2%." },
    [2565] = { en = "Increases chance to block by $s1% for $d, but will only block $n $lattack:attacks;.", description = "Aumenta del $s1% la probabilità di bloccare per $d, ma blocca solo $n $lattacco:attacchi;." },
    [2601] = { en = "Surrounds an ally with a shield of flame that inflicts $3054s1 Fire damage to nearby enemies every $t1 sec.  Lasts $d.", description = "Avvolge un alleato con uno scudo di fiamme che infligge $3054s1 danni da fuoco ai nemici vicini ogni $t1 secondi. Dura $d." },
    [2602] = { en = "Surrounds an ally with a shield of flame that inflicts $3055s1 Fire damage to nearby enemies every $t1 sec.  Lasts $d.", description = "Avvolge un alleato con uno scudo di fiamme che infligge $3055s1 danni da fuoco ai nemici vicini ogni $t1 secondi. Dura $d." },
    [2651] = { en = "Reduces the chance you'll be hit by melee and ranged attacks by $s1% for $d or until you are missed $n times.", description = "Riduce del $s1% la probabilità di essere colpito da attacchi in mischia e a distanza per $d o finché non ti mancano $n attacchi." },
    [2652] = { en = "The next melee attack against the caster will cause $2943s1 Shadow damage and reduce the attacker's melee attack power by $2943s2 for $2943d.", description = "Il prossimo attacco in mischia contro l'incantatore infligge $2943s1 danni da ombra e riduce di $2943s2 la potenza d'attacco in mischia dell'attaccante per $2943d." },
    [2823] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy for $2818o1 Nature damage over $2818d.  Stacks up to $2818u times on a single target.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $2818o1 danni da natura nell'arco di $2818d. Si accumula fino a $2818u volte sullo stesso bersaglio. $m3 cariche." },
    [2824] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy for $2819o1 Nature damage over $2819d.  Stacks up to $2819u times on a single target.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $2819o1 danni da natura nell'arco di $2819d. Si accumula fino a $2819u volte sullo stesso bersaglio. $m3 cariche." },
    [2835] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $2823h% chance of poisoning the enemy for $2818o1 Nature damage over $2818d.  Stacks up to $2818u times on a single target.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $2823h% di avvelenare il nemico, infliggendo $2818o1 danni da natura nell'arco di $2818d. Si accumula fino a $2818u volte sullo stesso bersaglio. $m3 cariche." },
    [2837] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $2824h% chance of poisoning the enemy for $2819o1 Nature damage over $2819d.  Stacks up to $2819u times on a single target.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $2824h% di avvelenare il nemico, infliggendo $2819o1 danni da natura nell'arco di $2819d. Si accumula fino a $2819u volte sullo stesso bersaglio. $m3 cariche." },
    [2893] = { en = "Attempts to cure $s2 poison effect on the target, and $3137s1 more poison effect every $t1 seconds for $d.", description = "Tenta di curare $s2 effetto di veleno sul bersaglio e $3137s1 altri effetti ogni $t1 secondi per $d." },
    [2908] = { en = "Soothes the target beast, reducing the range at which it will attack you by $s1 yards.  Only affects Beast targets level 40 or lower.  Lasts $d.", description = "Calma la bestia bersaglio, riducendo di $s1 metri la distanza alla quale ti attaccherà. Ha effetto solo sulle bestie di livello 40 o inferiore. Dura $d." },
    [2970] = { en = "Allows the friendly target to detect invisibility for $d.", description = "Permette al bersaglio alleato di individuare l'invisibilità per $d." },
    [3043] = { en = "Stings the target, reducing the target's chance to hit with attacks by $s1% for $d. Only one Sting per Hunter can be active on any one target.", description = "Punge il bersaglio, riducendo del $s1% la sua probabilità di colpire con gli attacchi per $d. Ogni cacciatore può mantenere una sola Puntura attiva sullo stesso bersaglio." },
    [3045] = { en = "Increases ranged and melee attack speed by $s1% for $d.", description = "Aumenta del $s1% la velocità d'attacco a distanza e in mischia per $d." },
    [3093] = { en = "Teaches Seal of Righteousness (Rank 2).", description = "Insegna Seal of Righteousness (grado 2)." },
    [3108] = { en = "Drains $s1 health from an enemy, healing the caster for up to half that amount.", description = "Sottrae $s1 salute a un nemico e cura l'incantatore fino a metà di tale ammontare." },
    [3130] = { en = "Inflicts normal damage plus $s2 to an enemy, and increases the time between its attacks by $s1% for $d.", description = "Infligge a un nemico i danni normali più $s2 e aumenta del $s1% l'intervallo tra i suoi attacchi per $d." },
    [3143] = { en = "Inflicts $s2 Frost damage to nearby enemies, stunning them for $d.", description = "Infligge $s2 danni da gelo ai nemici vicini e li stordisce per $d." },
    [3149] = { en = "Increases the Strength of nearby party members by $s1 for $d.", description = "Aumenta di $s1 la Forza dei membri del gruppo vicini per $d." },
    [3150] = { en = "Reduces the rate of an enemy's health regeneration by $s1%, in addition to lowering its Strength by $s2 and its Agility by $s3, for $d.", description = "Riduce del $s1% la rigenerazione della salute del nemico e ne riduce la Forza di $s2 e l'Agilità di $s3 per $d." },
    [3169] = { en = "Imbiber is immune to physical attacks for the next $d.", description = "Chi beve diventa immune agli attacchi fisici per i prossimi $d." },
    [3231] = { en = "Permanently enchant a cloak to give $7473s1 Agility.", description = "Incanta permanentemente un mantello per conferire $7473s1 Agilità." },
    [3237] = { en = "Reduces the Spirit of an enemy by $s1 for $d.", description = "Riduce lo Spirito di un nemico di $s1 per $d." },
    [3252] = { en = "Reduces an enemy's armor by $s1 for $d.", description = "Riduce l'armatura di un nemico di $s1 per $d." },
    [3385] = { en = "Increases the Physical damage dealt by the caster by $s2 and its movement speed by $s1% for $d.", description = "Aumenta di $s2 i danni fisici inflitti dall'incantatore e del $s1% la sua velocità di movimento per $d." },
    [3408] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, slowing their movement speed by $3409s1% for $3409d.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendone la velocità di movimento del $3409s1% per $3409d." },
    [3420] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $3408h% chance of poisoning the enemy, slowing their movement speed by $3409s1% for $3409d.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $3408h% di avvelenare il nemico, riducendone la velocità di movimento del $3409s1% per $3409d." },
    [3421] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $11202h% chance of poisoning the enemy, slowing their movement speed by $11201s1% for $11201d.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $11202h% di avvelenare il nemico, riducendone la velocità di movimento del $11201s1% per $11201d." },
    [3485] = { en = "Inflicts $o1 Shadow damage over $d. to nearby enemies.", description = "Infligge $o1 danni da ombra nell'arco di $d ai nemici vicini." },
    [3552] = { en = "Conjures a mana jade that can be used to instantly restore $10052s1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Evoca un mana jade che ripristina istantaneamente $10052s1 mana.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [3599] = { en = "Summons a Searing Totem with $s1 health at your feet for $d that repeatedly attacks an enemy within $3606r yards for $3606s1 Fire damage.", description = "Evoca ai tuoi piedi un Searing Totem con $s1 salute per $d. Attacca ripetutamente un nemico entro $3606r metri, infliggendo $3606s1 danni da fuoco." },
    [3680] = { en = "Gives the imbiber lesser invisibility for $d.", description = "Conferisce a chi beve un'invisibilità inferiore per $d." },
    [3742] = { en = "Deal $s1 Nature damage, increased by $1294477s1% per stack of Static Electricity. Deals $s2 times as much damage to Aquatic enemies.", description = "Infligge $s1 danni da natura, aumentati del $1294477s1% per ogni accumulo di Elettricità Statica. Infligge danni moltiplicati per $s2 ai nemici acquatici." },
    [4057] = { en = "Absorbs $s1 Fire damage. Lasts $d.", description = "Assorbe $s1 danni da fuoco. Dura $d." },
    [4060] = { en = "Transforms the target into a Leper Gnome, reducing its melee and spell damage by $s3 and its movement rate by $s2% for $d.", description = "Trasforma il bersaglio in uno Gnomo Lebbroso, riducendone i danni in mischia e quelli degli incantesimi di $s3 e la velocità di movimento del $s2% per $d." },
    [4073] = { en = "Activates your Mechanical Dragonling to fight for you for $d.", description = "Attiva il tuo Draghetto Meccanico, che combatte al tuo fianco per $d." },
    [4074] = { en = "Summons an Explosive Sheep which will charge at a nearby enemy and explode for $4050s1 damage. Lasts for 3 min or until it explodes.", description = "Evoca una Explosive Sheep che carica un nemico vicino ed esplode, infliggendo $4050s1 danni. Dura 3 min o fino all'esplosione." },
    [4079] = { en = "Gives invisibility for $d1.", description = "Conferisce invisibilità per $d1." },
    [4100] = { en = "Places the Goblin Land Mine on the ground. It will explode for $4043s1 Fire damage the next time a hostile creature passes near it. The mine has a duration of $d.", description = "Piazza una Goblin Land Mine. Esplode infliggendo $4043s1 danni da fuoco quando una creatura ostile le passa vicino. La mina dura $d." },
    [4246] = { en = "Grabs a target, holding them in place for $d while doing $o3 damage in that time.", description = "Afferra un bersaglio e lo trattiene per $d, infliggendogli $o3 danni durante l'effetto." },
    [4301] = { en = "Increases your chance to Parry with One-Handed Swords by 2%.", description = "Aumenta del 2% la probabilità di parare con le spade a una mano." },
    [4306] = { en = "Increases your chances to parry with a One-Handed Sword by 1%.", description = "Aumenta dell'1% la probabilità di parare con una spada a una mano." },
    [4495] = { en = "Increases your damage with Staves by $s1 and gives a 2% chance to stun the target for 8 seconds.", description = "Aumenta di $s1 i danni inflitti con i bastoni e conferisce una probabilità del 2% di stordire il bersaglio per 8 secondi." },
    [4526] = { en = "Dispels $s1 hostile effects on friendly targets and $s1 positive effects on hostile targets from targets next to the infernal.", description = "Dissipa $s1 effetti ostili dai bersagli alleati e $s1 effetti benefici dai bersagli nemici vicini all'infernale." },
    [4762] = { en = "Increases your chance to block with a Shield (not a Buckler) by 4% and reflects $s2% of hostile spells back at the caster.", description = "Aumenta del 4% la probabilità di bloccare con uno scudo (non un brocchiere) e riflette sull'incantatore il $s2% degli incantesimi ostili." },
    [4763] = { en = "Increases your chance to block with a Shield (not a Buckler) by 5% and reflects $s2% of hostile spells back at the caster.", description = "Aumenta del 5% la probabilità di bloccare con uno scudo (non un brocchiere) e riflette sull'incantatore il $s2% degli incantesimi ostili." },
    [4921] = { en = "Increases your chance to critical with Guns by $s1%.", description = "Aumenta del $s1% la probabilità di infliggere colpi critici con le armi da fuoco." },
    [4974] = { en = "Reduces an enemy's Stamina by $s1 and Spirit by $s2 for $d.", description = "Riduce la Tempra di un nemico di $s1 e lo Spirito di $s2 per $d." },
    [4987] = { en = "Cleanses a friendly target, removing $s1 poison effect, $s2 disease effect, and $s3 magic effect.", description = "Purifica un bersaglio alleato, rimuovendo $s1 effetto di veleno, $s2 effetto di malattia e $s3 effetto magico." },
    [5020] = { en = "A powerful brew that increases your strength by $s1 and decreases your intellect by $s2 for $d.", description = "Una bevanda potente che aumenta la Forza di $s1 e riduce l'Intelletto di $s2 per $d." },
    [5021] = { en = "Increases your health by $s1, but decreases your spirit by $s2 for $d.", description = "Aumenta la salute di $s1, ma riduce lo Spirito di $s2 per $d." },
    [5024] = { en = "Increase your run speed by $s1% for $d, but deals $s2 damage and drains $s3 mana every 2 seconds.", description = "Aumenta del $s1% la velocità di corsa per $d, ma infligge $s2 danni e sottrae $s3 mana ogni 2 secondi." },
    [5118] = { en = "The hunter takes on the aspects of a cheetah, increasing movement speed by $s1%.  If the hunter takes damage, $ghe:she; will be dazed for $15571d.  Only one Aspect can be active at a time.", description = "Il cacciatore assume l'aspetto di un ghepardo, aumentando la velocità di movimento del $s1%. Se subisce danni, $gil cacciatore:la cacciatrice; subisce un effetto di frastornamento per $15571d. Può essere attivo un solo Aspetto alla volta." },
    [5119] = { en = "Shows the location of all nearby beasts on the minimap for $d.", description = "Mostra sulla minimappa la posizione di tutte le bestie vicine per $d." },
    [5121] = { en = "Shows the location of all nearby giants on the minimap for $d.", description = "Mostra sulla minimappa la posizione di tutti i giganti vicini per $d." },
    [5137] = { en = "Inflicts $s1 Shadow damage to an enemy after $t1 sec.", description = "Infligge $s1 danni da ombra a un nemico dopo $t1 secondi." },
    [5143] = { en = "Launches Arcane Missiles at the enemy, causing $7268s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $7268s1 danni arcani ogni secondo per $d." },
    [5144] = { en = "Launches Arcane Missiles at the enemy, causing $7269s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $7269s1 danni arcani ogni secondo per $d." },
    [5145] = { en = "Launches Arcane Missiles at the enemy, causing $7270s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $7270s1 danni arcani ogni secondo per $d." },
    [5213] = { en = "Inflicts $s1 Fire damage every $t1 sec. to an enemy, increasing the time between its attacks by $s3% and its movement by $s2% for $d.", description = "Infligge $s1 danni da fuoco a un nemico ogni $t1 secondi, aumentando del $s3% l'intervallo tra i suoi attacchi e del $s2% il suo movimento per $d." },
    [5221] = { en = "Shred the target, causing $s2% damage plus 54 to the target.  Must be behind the target.  Awards $s3 combo $lpoint:points;.", description = "Sventra il bersaglio, infliggendo danni pari al $s2% più 54. Devi trovarti alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
